class Solution:
    def maxTaxiEarnings(self, n, rides):
        rides.sort(key=lambda r: r[1])
        m = len(rides)
        dp = [0] * (m + 1)
        for i in range(1, m + 1):
            s, e, tip = rides[i - 1]
            earn = e - s + tip
            j = i - 1
            while j > 0 and rides[j - 1][1] > s:
                j -= 1
            dp[i] = max(dp[i - 1], earn + dp[j])
        return dp[m]

