class Solution {
public:
    long long maxTaxiEarnings(int n, vector<vector<int>>& rides) {
        sort(rides.begin(), rides.end(),
             [](const vector<int>& a, const vector<int>& b) { return a[1] < b[1]; });
        int m = rides.size();
        vector<long long> dp(m + 1, 0);
        for (int i = 1; i <= m; i++) {
            int s = rides[i - 1][0], e = rides[i - 1][1], tip = rides[i - 1][2];
            long long earn = (long long)(e - s) + tip;
            int j = i - 1;
            while (j > 0 && rides[j - 1][1] > s) j--;
            dp[i] = max(dp[i - 1], earn + dp[j]);
        }
        return dp[m];
    }
};

