class Solution:
    def maxTaxiEarnings(self, n, rides):
        end_at = [[] for _ in range(n + 1)]
        for s, e, t in rides:
            end_at[e].append((s, t))
        dp = [0] * (n + 1)
        for p in range(1, n + 1):
            best = dp[p - 1]
            for s, t in end_at[p]:
                cand = dp[s] + (p - s) + t
                if cand > best:
                    best = cand
            dp[p] = best
        return dp[n]

