class Solution {
public:
    long long maxTaxiEarnings(int n, vector<vector<int>>& rides) {
        vector<vector<pair<int, int>>> endAt(n + 1);
        for (auto& r : rides) endAt[r[1]].push_back({r[0], r[2]});
        vector<long long> dp(n + 1, 0);
        for (int p = 1; p <= n; p++) {
            dp[p] = dp[p - 1];
            for (auto& [s, t] : endAt[p])
                dp[p] = max(dp[p], dp[s] + (long long)(p - s) + t);
        }
        return dp[n];
    }
};

