class Solution {
    public long maxTaxiEarnings(int n, int[][] rides) {
        List<List<int[]>> endAt = new ArrayList<>();
        for (int i = 0; i <= n; i++) endAt.add(new ArrayList<>());
        for (int[] r : rides) endAt.get(r[1]).add(new int[]{r[0], r[2]});
        long[] dp = new long[n + 1];
        for (int p = 1; p <= n; p++) {
            dp[p] = dp[p - 1];
            for (int[] st : endAt.get(p))
                dp[p] = Math.max(dp[p], dp[st[0]] + (long)(p - st[0]) + st[1]);
        }
        return dp[n];
    }
}

